import * as T from './vendor/three.module.min.js';
import {createWorld,height} from './world.js';
import {Survival,recipes,labels} from './economy.js';
const $=id=>document.getElementById(id);document.body.classList.add('menu');
const state=new Survival(),scene=new T.Scene();scene.background=new T.Color(0x9eb9b4);scene.fog=new T.FogExp2(0x9eb9b4,.018);
let renderer;try{renderer=new T.WebGLRenderer({canvas:$('world'),antialias:true,powerPreference:'high-performance'})}catch(e){$('start').textContent='WebGL indisponible sur ce navigateur';throw e}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
const camera=new T.PerspectiveCamera(65,innerWidth/innerHeight,.06,220);camera.rotation.order='YXZ';scene.add(camera);scene.add(new T.HemisphereLight(0xd0e1db,0x3e4228,2));const sun=new T.DirectionalLight(0xffe1a5,3.4);sun.position.set(-25,40,-30);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-28,right:28,top:28,bottom:-28,near:1,far:100});sun.shadow.bias=-.0005;scene.add(sun,sun.target);
const player={x:0,z:2,y:height(0,2),vy:0,yaw:0,pitch:-.08,vx:0,vz:0,grounded:true};let world,started=false,paused=false,time=0,last=performance.now(),cooldown=0,swing=0,target=null,toastTimer=0,autosave=0;const keys={},move={x:0,y:0};let running=false,held=false;
const tool=new T.Group();camera.add(tool);tool.position.set(.4,-.35,-.65);const woodMat=new T.MeshStandardMaterial({color:0x6d5438,roughness:.95});const ironMat=new T.MeshStandardMaterial({color:0x8e9490,roughness:.75,metalness:.2});const handle=new T.Mesh(new T.CylinderGeometry(.025,.034,.66,8),woodMat);handle.rotation.z=-.2;tool.add(handle);const head=new T.Mesh(new T.DodecahedronGeometry(.14,1),ironMat);head.scale.set(1.5,.8,.6);head.position.set(.08,.27,0);tool.add(head);tool.visible=false;
const ray=new T.Raycaster();ray.far=3.8;const center=new T.Vector2();
function notify(message){$('toast').textContent=message;$('toast').style.opacity=1;toastTimer=3}
function blocked(){return !started||paused||!$('panel').hidden}
function equip(k){if(!state.tools.includes(k)){notify('À fabriquer dans le sac');return}state.equipped=k;document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('selected',b.dataset.tool===k));tool.visible=k!=='hand';head.visible=k!=='spear';head.scale.set(k==='pick'?2.3:1.5,k==='pick'?.35:.8,.6);handle.scale.y=k==='spear'?2:1;renderPanel()}
function scan(){ray.setFromCamera(center,camera);const hits=ray.intersectObjects(world.nodes.filter(n=>n.amount>0).map(n=>n.mesh),true);target=hits[0]?.object.userData.node||null;if(!target){ // forgiving reach cone for small ground pickups
 let best=3;const dir=new T.Vector3();camera.getWorldDirection(dir);for(const n of world.nodes){if(n.amount<=0||n.kind==='deer')continue;const dx=n.x-player.x,dz=n.z-player.z,d=Math.hypot(dx,dz);if(d<best&&(dx*dir.x+dz*dir.z)/Math.max(.01,d)>.83){target=n;best=d}}
 }if(target){const names={wood:'Arbre · Bois',stone:'Roche · Pierre',ore:'Filon · Fer',bush:'Buisson · Baies & fibres',water:'Source · Eau',deer:target.hp>0?'Cerf · Chasser':'Cerf · Dépecer'};$('target').textContent=names[target.kind]+'\n'+(target.kind==='ore'&&state.equipped!=='pick'?'Pioche nécessaire':'E / Récolter');$('act').querySelector('small').textContent=target.kind==='deer'?'Chasser':target.kind==='water'?'Boire':'Récolter'}else{$('target').textContent='';$('act').querySelector('small').textContent='Récolter'}}
function act(){if(blocked()||cooldown>0)return;cooldown=.6;swing=.6;if(!target){notify('Approchez-vous et visez une ressource');return}const n=target;if(n.kind==='water'){state.thirst=100;notify('Vous buvez à la source');return}if(n.kind==='deer'){if(n.hp<=0){state.add('meat',3);state.add('hide',2);n.amount=0;state.depleted[n.id]=0;n.mesh.visible=false;notify('+3 viande · +2 peaux');return}if(state.equipped!=='spear'){notify('Fabriquez une lance pour chasser');return}if(state.stamina<12){notify('Endurance insuffisante');return}state.stamina-=12;n.hp-=35;n.fear=Math.max(n.fear||0,8);n.hitUntil=time+.28;notify(n.hp<=0?'Cerf abattu · approchez pour dépecer':'Touché · le cerf s’enfuit');return}const r=state.harvest(n);notify(r.error||r.text);if(!r.error){if(n.amount<=0)world.deplete(n)}renderPanel()}
function save(){if(!started)return false;try{localStorage.setItem('everwild-3d-v1',JSON.stringify({version:1,state:state.snapshot(),player:{x:player.x,z:player.z,yaw:player.yaw,pitch:player.pitch}}));return true}catch{notify('Sauvegarde indisponible : stockage du navigateur bloqué');return false}}
function load(){try{const d=JSON.parse(localStorage.getItem('everwild-3d-v1'));if(d?.version!==1||!state.restore(d.state))return false;for(const k of ['x','z','yaw','pitch'])if(Number.isFinite(d.player[k]))player[k]=d.player[k];player.x=Math.max(-100,Math.min(100,player.x));player.z=Math.max(-100,Math.min(100,player.z));player.y=height(player.x,player.z);for(const n of world.nodes)if(Object.hasOwn(state.depleted,n.id)){n.amount=Math.max(0,Math.min(n.amount,state.depleted[n.id]));n.mesh.visible=n.amount>0;if(n.amount<=0)world.deplete(n)}for(const f of state.fires)world.addFire(f.x,f.z);return true}catch{return false}}
function start(resume){if(resume&&!load()){notify('Sauvegarde illisible');return}started=true;paused=false;$('menu').hidden=true;document.body.classList.remove('menu');equip(state.equipped);notify('Visez le buisson et les rochers proches · E ou Récolter')}
function pause(){if(!started)return;paused=!paused;$('paused').hidden=!paused;resetInput()}
function resetInput(){for(const k of Object.keys(keys))keys[k]=false;move.x=move.y=0;held=running=false;$('stick').style.transform=''}
function inventory(){if(!started)return;$('panel').hidden=!$('panel').hidden;resetInput();renderPanel()}
function nearFire(){return state.fires.some(f=>Math.hypot(f.x-player.x,f.z-player.z)<4)}
function renderPanel(){const w=state.weight;$('contents').innerHTML='<div class="items">'+Object.entries(labels).map(([k,n])=>`<div class="item"><b>${state.bag[k]}</b>${n}</div>`).join('')+'</div>';$('recipes').innerHTML=Object.entries(recipes).map(([k,r])=>`<button class="recipe" data-craft="${k}" ${state.tools.includes(k)||!state.can(r.cost)?'disabled':''}><span>${r.name}<small>${Object.entries(r.cost).map(([id,q])=>q+' '+labels[id].toLowerCase()).join(' · ')}</small></span><span>${state.tools.includes(k)?'✓':'+'}</span></button>`).join('');$('panelnote').textContent=`Poids : ${w.toFixed(1)} / 40 kg. Au-delà, vous vous déplacez moins vite. Les feux sont placés devant vous. Source : à l’est de la clairière.`;$('goal').textContent=state.tools.includes('pick')?(state.bag.ore?'Établissez votre feu de camp':'Mine de fer : utilisez votre pioche'):'Récoltez du bois, de la pierre et des fibres';document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{const k=b.dataset.craft;if(k==='fire'&&state.fires.length>=20){notify('Limite de 20 feux atteinte');return}if(!state.craft(k))return;if(k==='fire'){const x=player.x-Math.sin(player.yaw)*2,z=player.z-Math.cos(player.yaw)*2;state.fires.push({x,z});world.addFire(x,z);notify('Feu de camp installé')}else{equip(k);notify(recipes[k].name+' fabriquée')}renderPanel()})}
$('start').onclick=()=>start(false);$('resume').onclick=()=>start(true);$('pause').onclick=pause;$('back').onclick=pause;$('bag').onclick=inventory;$('close').onclick=inventory;$('save').onclick=$('savepause').onclick=()=>{if(save())notify('Partie sauvegardée sur cet appareil')};$('eat').onclick=()=>{notify(state.eat()?'Repas consommé':'Vous n’avez pas de nourriture');renderPanel()};$('cook').onclick=()=>{if(!nearFire())return notify('Approchez-vous d’un feu de camp');if(!state.pay({meat:1,wood:1}))return notify('Il faut 1 viande crue et 1 bois');state.add('cooked',1);notify('Viande cuite préparée');renderPanel()};$('rest').onclick=()=>{if(!nearFire())return notify('Approchez-vous d’un feu de camp');state.health=Math.min(100,state.health+20);state.stamina=100;state.hunger=Math.max(0,state.hunger-5);notify('Vous vous réchauffez au feu')};$('fullscreen').onclick=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen()}catch{notify('Plein écran non disponible ici')}};$('quality').onchange=()=>{renderer.setPixelRatio(Math.min(devicePixelRatio,Number($('quality').value)));renderer.shadowMap.enabled=$('quality').value!=='1'};
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>equip(b.dataset.tool));
function jump(){if(!blocked()&&player.grounded&&state.stamina>=8){player.vy=5.1;player.grounded=false;state.stamina-=8}}$('jump').onpointerdown=e=>{e.preventDefault();jump()};$('act').onpointerdown=e=>{e.preventDefault();$('act').setPointerCapture(e.pointerId);held=true;act()};for(const event of ['pointerup','pointercancel'])$('act').addEventListener(event,()=>held=false);$('sprint').onpointerdown=e=>{e.preventDefault();running=!running;$('sprint').style.borderColor=running?'#e7d8aa':'#a8996755'};
let joyId=null,joyCenter={x:0,y:0};$('joystick').onpointerdown=e=>{if(blocked())return;joyId=e.pointerId;$('joystick').setPointerCapture(e.pointerId);const b=$('joystick').getBoundingClientRect();joyCenter={x:b.x+b.width/2,y:b.y+b.height/2};joy(e)};function joy(e){if(e.pointerId!==joyId)return;const dx=e.clientX-joyCenter.x,dy=e.clientY-joyCenter.y,len=Math.hypot(dx,dy),scale=Math.min(1,35/Math.max(1,len));move.x=dx*scale/35;move.y=dy*scale/35;$('stick').style.transform=`translate(${move.x*30}px,${move.y*30}px)`}$('joystick').onpointermove=joy;for(const ev of ['pointerup','pointercancel'])$('joystick').addEventListener(ev,()=>{joyId=null;move.x=move.y=0;$('stick').style.transform=''});
let look=null;$('world').onpointerdown=e=>{if(blocked())return;look={id:e.pointerId,x:e.clientX,y:e.clientY};$('world').setPointerCapture(e.pointerId)};$('world').onpointermove=e=>{if(!look||e.pointerId!==look.id||blocked())return;player.yaw-=(e.clientX-look.x)*.004;player.pitch=Math.max(-1.2,Math.min(1.2,player.pitch-(e.clientY-look.y)*.003));look.x=e.clientX;look.y=e.clientY};for(const ev of ['pointerup','pointercancel'])$('world').addEventListener(ev,()=>look=null);
window.addEventListener('keydown',e=>{if(e.target.tagName==='SELECT')return;keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space')jump();if(e.code==='KeyE')act();if(e.code==='KeyI'||e.code==='KeyC')inventory();if(e.code==='Escape'){if(!$('panel').hidden)inventory();else pause()}if(/^Digit[1-4]$/.test(e.code))equip(['hand','axe','pick','spear'][Number(e.code.slice(-1))-1])});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{resetInput();if(started&&!paused){paused=true;$('paused').hidden=false}});document.addEventListener('visibilitychange',()=>{if(document.hidden){save();resetInput();if(started){paused=true;$('paused').hidden=false}}});window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
function update(dt){time+=dt;cooldown=Math.max(0,cooldown-dt);swing=Math.max(0,swing-dt);toastTimer-=dt;if(toastTimer<0)$('toast').style.opacity=0;
 if(!blocked()){const f=(keys.KeyW||keys.KeyZ||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-move.y;const side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.KeyQ||keys.ArrowLeft?1:0)+move.x;const length=Math.max(1,Math.hypot(f,side));const sprint=(keys.ShiftLeft||running)&&state.stamina>3&&Math.abs(f)+Math.abs(side)>.1;const speed=(sprint?5:2.5)*(state.weight>40?.55:1)*(state.hunger<10?.7:1);const vx=(Math.cos(player.yaw)*side-Math.sin(player.yaw)*f)*speed/length,vz=(-Math.sin(player.yaw)*side-Math.cos(player.yaw)*f)*speed/length;player.vx=T.MathUtils.damp(player.vx,vx,12,dt);player.vz=T.MathUtils.damp(player.vz,vz,12,dt);let nx=player.x+player.vx*dt,nz=player.z+player.vz*dt;for(const c of world.colliders){if(c.amount<=0)continue;const dx=nx-c.x,dz=nz-c.z,d=Math.hypot(dx,dz),r=c.r+.3;if(d<r){nx=c.x+dx/Math.max(d,.001)*r;nz=c.z+dz/Math.max(d,.001)*r}}player.x=T.MathUtils.clamp(nx,-100,100);player.z=T.MathUtils.clamp(nz,-100,100);player.vy-=14*dt;player.y+=player.vy*dt;const floor=height(player.x,player.z);if(player.y<floor){player.y=floor;player.vy=0;player.grounded=true}state.tick(dt,sprint);world.update(time,dt,player);if(held||keys.KeyE)act();autosave+=dt;if(autosave>30){save();autosave=0}if(state.health<=0){state.health=65;state.hunger=50;state.thirst=50;player.x=0;player.z=2;player.y=height(0,2);notify('Épuisé : vous reprenez connaissance dans la clairière')}
 }
 const bob=!blocked()?Math.sin(time*9)*Math.min(.025,Math.hypot(player.vx,player.vz)*.008):0;camera.position.set(player.x,player.y+1.65+bob,player.z);camera.rotation.set(player.pitch,player.yaw,0);tool.rotation.z=-.2-Math.sin(swing/.6*Math.PI)*1.05;tool.rotation.x=Math.sin(swing/.6*Math.PI)*.8;tool.position.y=-.35+bob;sun.position.set(player.x-25,40,player.z-30);sun.target.position.set(player.x,0,player.z);if(world&&started)scan();$('health').value=state.health;$('stamina').value=state.stamina;$('hunger').textContent='Faim '+Math.round(state.hunger);$('thirst').textContent='Eau '+Math.round(state.thirst);const deg=((player.yaw*180/Math.PI)%360+360)%360;$('compass').textContent=['N','NO','O','SO','S','SE','E','NE'][Math.round(deg/45)%8]+' · '+Math.round(deg)+'°';renderer.render(scene,camera)}
async function boot(){try{world=await createWorld(scene);$('start').disabled=false;$('start').textContent='Entrer dans la forêt';try{$('resume').hidden=!localStorage.getItem('everwild-3d-v1')}catch{}renderPanel();function frame(now){const dt=Math.min(.04,(now-last)/1000);last=now;update(dt);requestAnimationFrame(frame)}requestAnimationFrame(frame)}catch(e){console.error(e);$('start').textContent='Erreur de chargement · rechargez la page';$('menu').querySelector('.intro').textContent=e.message}}
boot();
